INSERT INTO shop_items (name, category, price, currency_type, shop_area, purchase_limit, description, stock) VALUES
('Bát Nhã Ma Kinh (Kinh Da Dê Tà Thuật)', 'Trấn vật cầm tay', 4500, 'HUA_TIEN', 'Hiếm', '01 cuốn / người',
 'Cuốn kinh bằng bìa da dê đen ghi chép các câu chú tà thuật bị cấm. Mở kinh đọc chú tác dụng lên Bản thân, tăng 150% Sát thương trong 3 cmt. Đổi lại, Tốc độ di chuyển của bạn bị giảm 60% (tê liệt chân trái tạm thời - tag vàng) trong suốt thời gian cầm cuốn kinh. Tương thích Dị sự: Đứng từ xa xả ma thuật dồn sát thương ở Dị sự cấp Phỉ. ⚠️ Tác dụng phụ / Lưu ý: Tốc độ di chuyển bị chậm biến bạn thành mục tiêu cực kỳ dễ bị các con quỷ cận chiến áp sát xé xác.', 99),
('Thái Cực Hoàn Không Phù (Bùa Xoáy Âm Dương)', 'Bùa chú phòng thủ', 400, 'AM_DUC', 'Hiếm', '03 lá / tháng',
 'Lá bùa đen trắng vẽ hình xoáy nước âm dương bẫy năng lượng. Dán trước ngực tác dụng lên Các đòn đánh chưởng / đạn ma thuật tầm xa của Lệ Quỷ, hút trọn và tiêu biến hoàn toàn 2 đòn chưởng đầu tiên nhắm vào bạn. Tương thích Dị sự: Mở đường chống quỷ bắn xa ở Dị sự cấp Hoàng. ⚠️ Tác dụng phụ / Lưu ý: Bùa chỉ hút được đòn ma thuật tầm xa, hoàn toàn không có tác dụng với đòn cào xé cận chiến.', 99),
('Âm Phong Hoán Vũ Phù (Bùa Cuồng Phong)', 'Bùa chú đánh đổi', 2000, 'CONG_DUC', 'Hiếm', '02 lá / tháng',
 'Lá bùa đen tuyền mang theo cuồng phong, xé tan mọi sự kiềm kẹp. Dán vào ngực tác dụng lên Bản thân, miễn nhiễm toàn bộ hiệu ứng Choáng, Đóng Băng, Giữ Chân, Kéo Lê trong 5 cmt. Đổi lại, Giáp phòng thủ bị giảm về 0 và nhận thêm 30% sát thương (tag đỏ nhạt). Tương thích Dị sự: Thoát khỏi chuỗi khống chế liên tục của Boss ở Dị sự cấp Hoàng và Phỉ. ⚠️ Tác dụng phụ / Lưu ý: Tuy không bị giữ chân nhưng bạn sẽ bị mất máu rất nhanh nếu hứng trọn các đòn đánh thường của quỷ.', 99);
